insert into categories (id, slug, label, tagline, blurb, image, sort_order) values
  (1, 'fragrance', 'Fragrance & Attar', 'Oud, musk and amber — bottled by hand', 'Alcohol-free attar oils, roll-on perfume, body mists and bakhoor sourced for depth and longevity.', '/images/cat-fragrance.webp', 1),
  (2, 'skincare', 'Skincare & Beauty', 'Korean-grade care, everyday glow', 'Sunscreen, serums, moisturiser and lip colour chosen for Bangladeshi weather and skin tones.', '/images/cat-skincare.webp', 2),
  (3, 'haircare', 'Hair Care & Accessories', 'Silk, satin and gentle styling', 'Silk scrunchies, satin bonnets, claw clips and heatless styling sets that protect your hair.', '/images/cat-haircare.webp', 3),
  (4, 'fashion', 'Fashion & Lifestyle', 'Anti-tarnish, everyday elegance', 'Anti-tarnish jewellery, canvas totes, mini purses and card holders built to last past one season.', '/images/cat-fashion.webp', 4),
  (5, 'gifts', 'Accessories & Gift', 'Boxed, wrapped, ready to give', 'Curated gift boxes, jewellery, makeup tools and organisers — including Under ৳499 and Under ৳999 sets.', '/images/cat-gifts.webp', 5)
